from pathlib import Path
import csv,json,hashlib,collections,datetime,re
p=Path('.work/windows-timing-followup-20261116/etw/admin-20261116T074942-5bd67094')
j=json.loads((p/'capture.json').read_text());sha=lambda f:hashlib.sha256(f.read_bytes()).hexdigest()
assert j['status']=='samples_captured' and j['stop_exit']==0 and j['cleanup_confirmed'] and sha(p/'schedule.etl')==j['etl_sha256']
samples=j['samples']; tids={s['observer']['primary_tid'] for s in samples};pids={s['observer']['pid'] for s in samples}
events=collections.Counter();threads={};slices=collections.defaultdict(list);dpc=collections.defaultdict(list);issues=[];last={};raw=[];invalid=[]
def pid(s):return int(re.search(r'\(\s*(\d+)\)',s)[1])
for row in csv.reader((p/'events.csv').open(errors='replace'),skipinitialspace=True):
 if not row or len(row)<2:continue
 name=row[0].strip()
 try:t=int(row[1])
 except ValueError:continue
 events[name]+=1
 if name.startswith('InvalidEvent'):invalid.append(row[:10])
 if name in ['T-Start','T-End'] and pid(row[2]) in pids:
  tid=int(row[3]);threads.setdefault(tid,{'pid':pid(row[2])})[name]=t
 if name=='CSwitch':
  cpu=int(row[16]);new=int(row[3]);old=int(row[9]);duration=int(row[15]);begin=t-duration
  if cpu in last and last[cpu][1]!=old:issues.append({'cpu':cpu,'time':t,'expected':last[cpu][1],'old':old})
  last[cpu]=(t,new)
  if old in tids:
   slices[old].append({'start_us':begin,'end_us':t,'cpu':cpu,'old_priority':int(row[10]),'old_state':row[12],'wait_reason':row[13]})
 if name=='DPC_ISR_CSWITCH_PCT' and int(row[7]) in tids:
  dpc[int(row[7])].append({'start_us':int(row[2]),'end_us':t,'cpu':int(row[8]),'dpc_isr_us':int(row[5])})
trace_start=datetime.datetime.fromisoformat('2026-11-16T07:49:42.2987597+00:00')
def overlap(a,b,c,d):return max(0,min(b,d)-max(a,c))
rows=[]
for s in samples:
 tid=s['observer']['primary_tid'];q=s['observer']['queries'];runs=slices[tid];adjust=dpc[tid]
 assert threads[tid]['pid']==s['observer']['pid'] and 'T-Start'in threads[tid] and 'T-End'in threads[tid]
 assert len(runs)==len(adjust) and all(abs(a['start_us']-b['start_us'])<=1 and (a['end_us'],a['cpu'])==(b['end_us'],b['cpu']) for a,b in zip(runs,adjust))
 assert runs[0]['start_us']>=threads[tid]['T-Start']
 gross=sum(x['end_us']-x['start_us'] for x in runs);di=sum(x['dpc_isr_us'] for x in adjust)
 api_lifetime=sum(q[-1]['primary_thread'].values())/1000
 # UTC is sampled after perf_start and before process_query_end. Use it only for an approximate window; lifetime needs no clock join.
 bounds=[(datetime.datetime.fromisoformat(x['utc'])-trace_start).total_seconds()*1e6 for x in q[:2]]
 window_gross=sum(overlap(x['start_us'],x['end_us'],*bounds) for x in runs)
 rows.append({'kind':s['kind'],'pid':s['observer']['pid'],'tid':tid,'thread_events':threads[tid],'slices':len(runs),'cpus':sorted(set(x['cpu'] for x in runs)),'priorities':sorted(set(x['old_priority'] for x in runs)),'lifetime_scheduled_gross_ms':gross/1000,'lifetime_dpc_isr_ms':di/1000,'lifetime_scheduled_excluding_dpc_isr_ms':(gross-di)/1000,'lifetime_primary_api_ms':api_lifetime/1000,'api_minus_scheduled_excluding_ms':(api_lifetime-gross+di)/1000,'measured_process_api_ms':s['cpu_us']/1000,'measured_wall_ms':s['wall_us']/1000,'approx_utc_window_us':bounds,'approx_window_scheduled_gross_ms':window_gross/1000,'boundary_process_query_bracket_us':[(x['process_query_end_ns']-x['perf_start_ns'])/1000 for x in q[:2]],'process_minus_primary_interval_ms':(sum(q[1]['process'].values())-sum(q[0]['process'].values())-sum(q[1]['primary_thread'].values())+sum(q[0]['primary_thread'].values()))/1e6})
def xperf_thread_report(name):
 result={}
 for r in csv.reader((p/name).open(errors='replace'),skipinitialspace=True):
  if len(r)!=3:continue
  try:value,tid=int(r[0]),int(r[2])
  except ValueError:continue
  if tid in tids:result[tid]=value
 assert set(result)==tids
 return result
net=xperf_thread_report('cswitch-net.txt');gross_report=xperf_thread_report('cswitch-gross.txt')
for r in rows:
 tid=r['tid'];r['xperf_lifetime_gross_ms']=gross_report[tid]/1000;r['xperf_lifetime_net_ms']=net[tid]/1000;r['xperf_lifetime_dpc_isr_ms']=(gross_report[tid]-net[tid])/1000
 r['xperf_api_minus_net_ms']=r['lifetime_primary_api_ms']-net[tid]/1000
 r['parser_minus_xperf_net_us']=round(r['lifetime_scheduled_excluding_dpc_isr_ms']*1000-net[tid],6)
 assert abs(r['parser_minus_xperf_net_us'])<=r['slices']*2
 r['last_switch_after_thread_end_event_us']=slices[tid][-1]['end_us']-threads[tid]['T-End']
report={'etl_sha256':j['etl_sha256'],'etl_bytes':j['etl_bytes'],'capture_status':j['status'],'cleanup_confirmed':j['cleanup_confirmed'],'event_counts':dict(events),'invalid_events':invalid,'all_cpu_cswitch_old_new_chain_mismatch_count':len(issues),'chain_mismatch_examples':issues[:5],'rows':rows,'source_script':Path(__file__).read_text(),'limits':['Single profiled session; not AA calibration or performance comparison','ETW slice residence is scheduler-derived elapsed time, not independent hardware instructions or thread CPU accuracy proof','Xperf -exc_dpcisr supplied DPC_ISR_CSWITCH_PCT per slice; CSV integer microsecond rounding applies','Approximate interval joins use observer UTC against trace UTC, not a direct QPC-marker join; lifetime joins use target T-Start/T-End and TID identity instead','System configuration invalid event warning retained; lost event/buffer counters are zero, which alone is not proof of no unobserved data error','No frequency, sampling stacks or instruction attribution in this trace']}
report['xperf_warning']={'event_number':1336047,'time_us':44493519,'provider':'01853a65-418f-4f36-aefc-dc0f1d2fd235','type':'0x0c','version':2,'name_from_tracestats':'SysConfig: Logical Disks','mof_length':112,'scope':'After all target threads ended; warning is decoder-specific and not proof every event valid. No InvalidEvent CSV row emitted.'}
assert report['xperf_warning']['time_us']>max(slices[tid][-1]['end_us'] for tid in tids)
report['tracestats']=(p/'timespan.txt').read_text()
report['report_hashes']={name:sha(p/name) for name in ['events.csv','tracestats.txt','timespan.txt','cswitch-net.txt','cswitch-gross.txt','dpcisr.txt']}
(p/'analysis.json').write_text(json.dumps(report,indent=2)+'\n')
for x in rows:print({k:v for k,v in x.items() if k not in ['approx_utc_window_us','thread_events']})
print('Invalid',invalid,'chain mismatches',len(issues))

